after.content:
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
Push-Location $root
try {
  & .\gradlew.bat stage2FoundationCheck --offline --rerun-tasks
  if ($LASTEXITCODE -ne 0) { throw "Stage 2 foundation gate failed: $LASTEXITCODE" }
  & node .\scripts\verify-module-boundaries.mjs
  if ($LASTEXITCODE -ne 0) { throw "module boundary gate failed: $LASTEXITCODE" }
  & node .\scripts\verify-naming.mjs
  if ($LASTEXITCODE -ne 0) { throw "naming gate failed: $LASTEXITCODE" }
} finally {
  Pop-Location
}
